package com.campuscompanion.common.storage;

import java.time.Duration;
import java.time.Instant;

/**
 * Where uploaded files are kept. The application talks to file storage only through this interface,
 * so tests can use a storage held in memory. Every method throws {@link
 * StorageUnavailableException} when storage cannot be reached.
 */
public interface StorageClient {

  /** Stores a file at the given path. The path is always generated by the server. */
  void upload(String path, byte[] content, String contentType);

  /** Removes the file at the given path. Removing a file that is not there is not an error. */
  void delete(String path);

  /**
   * A link that lets its holder read one file for a short time. It is issued only after the caller
   * has checked that the user may read the resource.
   *
   * @param downloadName the file name the browser should save the file under, or null when the file
   *     is to be shown in the page
   */
  SignedLink signedUrl(String path, Duration validFor, String downloadName);

  record SignedLink(String url, Instant expiresAt) {}
}
